ROLE_BY_GROUP = {
    "grp-supply-viewers": "viewer",
    "grp-supply-buyers": "buyer",
    "grp-supply-senior": "senior_buyer",
}
APPROVAL_LIMIT_EUR = {"buyer": 25_000, "senior_buyer": 250_000}

def roles_from_claims(claims: dict) -> set[str]:
    return {ROLE_BY_GROUP[g] for g in claims.get("groups", []) if g in ROLE_BY_GROUP}

def can_approve(user: dict, order: dict) -> bool:
    if order["created_by"] == user["oid"]:
        return False  # no self-approval
    limit = max((APPROVAL_LIMIT_EUR.get(r, 0) for r in user["roles"]), default=0)
    return order["total_eur"] <= limit

@app.post("/orders/{order_id}/approve")
def approve(order_id: str, user=Depends(current_user)):  # 401 if token invalid
    order = load_order(order_id)
    if not can_approve(user, order):
        raise HTTPException(status_code=403, detail="Not allowed to approve this order")
    return mark_approved(order, approved_by=user["oid"])

import json, redis
r = redis.Redis(host="rates-cache", port=6379)
TTL_SECONDS = 15 * 60

def cache_key(product_id: str, lvr_band: str) -> str:
    return f"rates:v3:{product_id}:{lvr_band}"

def get_rates(product_id: str, lvr_band: str) -> dict:
    key = cache_key(product_id, lvr_band)
    hit = r.get(key)
    if hit is not None:
        metrics.incr("rates_cache.hit")
        return json.loads(hit)
    metrics.incr("rates_cache.miss")
    rates = rates_db.query(product_id, lvr_band)  # slow: 600-1500 ms
    r.set(key, json.dumps(rates), ex=TTL_SECONDS)
    return rates

def on_rates_published(product_id: str):
    # called by the rates team's publish job
    for key in r.scan_iter(f"rates:v3:{product_id}:*"):
        r.delete(key)

