HIGH_RISK = {"propose_rent_credit"}

def run_tool(call, ctx):
    if call.name == "search_leases":
        # scope enforced in code, not in the prompt
        return leases.search(call.args["query"], tenant_id=ctx.verified_tenant_id)
    if call.name == "create_ticket":
        return tickets.create(tenant_id=ctx.verified_tenant_id, **call.args)
    if call.name in HIGH_RISK:
        amount = float(call.args["amount_sek"])
        req = approvals.create(
            kind="rent_credit", tenant_id=ctx.verified_tenant_id,
            amount_sek=amount, reason=call.args["reason"],
            source_email_id=ctx.email_id, status="pending_manager")
        audit.log("approval_requested", request_id=req.id, amount_sek=amount)
        return {"status": "pending_approval", "request_id": req.id}
    raise PermissionError(f"Tool not allowed: {call.name}")
